import { update_timesheet } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    approveReporting: Boolean,
    timesheetitems: Object
  },
  data() {
    return {
      loading: false,
      approveloading: false,
      fixed: true,
      timeRecords: [],
      timeSheetHeaders: [{
        title: "Date",
        key: "timesheet_from_date",
        sortable: false
      }, {
        title: "Project Name",
        key: "project_name",
        sortable: false
      }, {
        title: "Activity",
        key: "activity_name",
        sortable: false
      }, {
        title: "Time Spent",
        key: "work_duartion",
        sortable: false
      }, {
        title: "Comments",
        key: "comments",
        sortable: false
      }]
    };
  },
  watch: {
    approveReporting: {
      async handler() {
        this.timeRecords = this.timesheetitems.timesheet_details;
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async reject_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(update_timesheet, {
          input: {
            action_type: "UPDATE_STATUS",
            timesheet_id: this.timesheetitems.timesheet_id,
            timesheet_status: "REJECTED"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.update_timesheet);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    async approve_mutation() {
      this.approveloading = true;
      try {
        let result = await API.graphql(graphqlOperation(update_timesheet, {
          input: {
            action_type: "UPDATE_STATUS",
            timesheet_id: this.timesheetitems.timesheet_id,
            timesheet_status: "APPROVED"
          }
        }));
        this.approveloading = false;
        var response = JSON.parse(result.data.update_timesheet);
        this.approveloading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.approveloading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
